+/****************************************************************************
+ * app/velaguard/velaguard_pwm.c
+ *
+ * VelaGuard - vgpwm: drive the DO1 passive buzzer through /dev/pwm0
+ *
+ * Usage:
+ *   vgpwm [hz] [duty-percent] [duration-ms]
+ *   default: 2700 Hz, 50 %, 3000 ms
+ *
+ * This is the minimal user-space driver exercise:
+ *   open -> SETCHARACTERISTICS -> START -> sleep -> STOP -> close
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+#include <sys/ioctl.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <unistd.h>
+#include <fcntl.h>
+#include <errno.h>
+
+#include <fixedmath.h>          /* b16HALF, uitoub16, b16divi */
+#include <nuttx/timers/pwm.h>   /* pwm_info_s, PWMIOC_* */
+
+/****************************************************************************
+ * Public Functions
+ ****************************************************************************/
+
+int main(int argc, FAR char *argv[])
+{
+  struct pwm_info_s info;
+  uint32_t hz  = 2700;
+  uint32_t pct = 50;
+  uint32_t ms  = 3000;
+  int fd;
+  int ret;
+
+  /* Parse optional arguments: vgpwm [hz] [pct] [ms] */
+
+  if (argc > 1)
+    {
+      hz = (uint32_t)strtoul(argv[1], NULL, 10);
+    }
+
+  if (argc > 2)
+    {
+      pct = (uint32_t)strtoul(argv[2], NULL, 10);
+    }
+
+  if (argc > 3)
+    {
+      ms = (uint32_t)strtoul(argv[3], NULL, 10);
+    }
+
+  /* Basic sanity checks (the driver rejects silly values anyway) */
+
+  if (hz == 0 || pct == 0 || pct > 99 || ms == 0)
+    {
+      fprintf(stderr,
+              "vgpwm: bad arguments (hz>=1, 1<=pct<=99, ms>=1)\n");
+      return 1;
+    }
+
+  printf("vgpwm: %lu Hz, %lu%%, %lu ms\n",
+         (unsigned long)hz, (unsigned long)pct, (unsigned long)ms);
+
+  /* 1. Open the PWM device. O_RDONLY is the convention: the PWM driver
+   *    does not use read()/write(), everything goes through ioctl().
+   */
+
+  fd = open("/dev/pwm0", O_RDONLY);
+  if (fd < 0)
+    {
+      fprintf(stderr, "vgpwm: open /dev/pwm0 failed: %d\n", errno);
+      return 1;
+    }
+
+  /* 2. Describe the pulse train.
+   *
+   *    duty is a ub16 fixed-point value: 0x00000000 .. 0x00010000,
+   *    so 50% = 0x00008000.  uitoub16(pct) makes a percentage a ub16
+   *    number (e.g. 50 -> 0x00320000), b16divi(...,100) divides it
+   *    back down to 0x00008000.
+   */
+
+  info.frequency = hz;
+  info.duty      = b16divi(uitoub16(pct), 100);
+
+  ret = ioctl(fd, PWMIOC_SETCHARACTERISTICS,
+              (unsigned long)((uintptr_t)&info));
+  if (ret < 0)
+    {
+      fprintf(stderr, "vgpwm: ioctl(PWMIOC_SETCHARACTERISTICS) failed: %d\n",
+              errno);
+      goto errout;
+    }
+
+  /* 3. Start the pulse train. */
+
+  ret = ioctl(fd, PWMIOC_START, 0);
+  if (ret < 0)
+    {
+      fprintf(stderr, "vgpwm: ioctl(PWMIOC_START) failed: %d\n", errno);
+      goto errout;
+    }
+
+  /* 4. Let it ring for the requested duration. */
+
+  usleep(ms * 1000);
+
+  /* 5. Stop and close. */
+
+  ret = ioctl(fd, PWMIOC_STOP, 0);
+  if (ret < 0)
+    {
+      fprintf(stderr, "vgpwm: ioctl(PWMIOC_STOP) failed: %d\n", errno);
+      goto errout;
+    }
+
+  close(fd);
+  return 0;
+
+errout:
+  close(fd);
+  return 1;
+}
